tool_input.command:
python3 - <<'EOF'
p='src/features/users/components/users-list.tsx'
s=open(p).read()
s=s.replace("""import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { formatDate } from '@/utils/format';
""","""import { Download } from 'lucide-react';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import { Input, Select } from '@/components/ui/form';
import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { ROLES } from '@/lib/authorization';
import { User } from '@/types/api';
import { CsvColumn, downloadCsv, toCsv } from '@/utils/csv';
import { formatDate } from '@/utils/format';
""")
s=s.replace("""export const UsersList = () => {
  const usersQuery = useUsers();
""","""const ALL_ROLES = 'ALL';

const roleOptions = [
  { label: 'All roles', value: ALL_ROLES },
  { label: 'Admin', value: ROLES.ADMIN },
  { label: 'User', value: ROLES.USER },
];

const csvColumns: CsvColumn<User>[] = [
  { header: 'Name', value: (user) => `${user.firstName} ${user.lastName}` },
  { header: 'Email', value: (user) => user.email },
  { header: 'Role', value: (user) => user.role },
  { header: 'Joined', value: (user) => formatDate(user.createdAt) },
];

const matchesSearch = (user: User, search: string) => {
  const term = search.trim().toLowerCase();
  if (!term) return true;

  return [`${user.firstName} ${user.lastName}`, user.email].some((value) =>
    value.toLowerCase().includes(term),
  );
};

export const UsersList = () => {
  const usersQuery = useUsers();
  const [search, setSearch] = React.useState('');
  const [role, setRole] = React.useState<string>(ALL_ROLES);
""")
s=s.replace("""  return (
    <Table
      data={users}
""","""  const shownUsers = users.filter(
    (user) =>
      (role === ALL_ROLES || user.role === role) && matchesSearch(user, search),
  );

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-end gap-4">
        <div className="w-full sm:w-72">
          <Input
            type="search"
            label="Search"
            placeholder="Search by name or email"
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            registration={{}}
          />
        </div>
        <div className="w-full sm:w-48">
          <Select
            label="Role"
            options={roleOptions}
            defaultValue={ALL_ROLES}
            registration={{
              name: 'role',
              onChange: async (event: { target: { value: string } }) => {
                setRole(event.target.value);
              },
            }}
          />
        </div>
        <Button
          className="sm:ml-auto"
          variant="outline"
          icon={<Download className="size-4" />}
          disabled={!shownUsers.length}
          onClick={() => downloadCsv('users.csv', toCsv(shownUsers, csvColumns))}
        >
          Export CSV
        </Button>
      </div>
      <Table
        data={shownUsers}
""",1)
head,tail=s.split("      <Table\n        data={shownUsers}\n",1)
tail="\n".join(("  "+l if l.strip() else l) for l in tail.split("\n"))
tail=tail.replace("    );\n  };","    </div>\n  );\n};")
open(p,'w').write(head+"      <Table\n        data={shownUsers}\n"+tail.rstrip()+"\n")
EOF
tail -50 src/features/users/components/users-list.tsx; npx prettier --check src/features/users/components/users-list.tsx src/utils/csv.ts
